HEAD = {
    'I18N': lambda f: f"**Tier:** {f['tier']} · **Locale(s):** {f['loc_']} · **Deploy unit:** {f['unit']} · **Generated?** {f['gen']} · **Origin:** {f['origin']}",
    'TERM': lambda f: f"**Tier:** {f['tier']} · **Locale(s):** {f['loc_']} · **Deploy unit:** {f['unit']} · **Term source:** {f['term']} · **Origin:** {f['origin']}",
    'HC': lambda f: f"**Tier:** {f['tier']} · **Locale(s):** {f['loc_']} · **Deploy unit:** {f['unit']} · **Target set:** {f['target']} · **Proposed key:** {f['key']} · **Origin:** {f['origin']}",
    'FONT': lambda f: f"**Tier:** {f['tier']} · **Locale(s):** {f['loc_']} · **Deploy unit:** {f['unit']} · **Origin:** {f['origin']}",
}

(OUT / 'findings').mkdir(parents=True, exist_ok=True)
catalog, idmap = [], {}
for f in F:
    f['prefix'] = f['id'].split('-')[0]
    status = 'OPEN — Sprint 0 decision: fix inside the open PR before merging, or later in the policy sprint.' if f.get('s0') else 'OPEN'
    lines = [f"# {f['id']}: {f['title']}", HEAD[f['prefix']](f), '', '## Location'] + [f'- {x}' for x in f['loc']] \
        + ['', '## Evidence'] + [f'- {x}' for x in f['ev']] + ['', '## Fix', f"- {f['fix']}", '', '## Status', status, '']
    assert len(lines) <= 26, (f['id'], len(lines))
    (OUT / 'findings' / f"{f['id']}.md").write_text('\n'.join(lines), encoding='utf-8', newline='\n')
    catalog.append({k: f[k] for k in ('id', 'prefix', 'tier', 'loc_', 'unit', 'origin', 'title')} | {'sprint0': bool(f.get('s0'))})
    idmap[f['id']] = f['src']

ids = [f['id'] for f in F]
assert len(ids) == len(set(ids))
(OUT / 'evidence/catalog.json').write_text(json.dumps(catalog, ensure_ascii=False, indent=1) + '\n', encoding='utf-8', newline='\n')
(OUT / 'evidence/id-map.json').write_text(json.dumps(idmap, ensure_ascii=False, indent=1) + '\n', encoding='utf-8', newline='\n')
from collections import Counter
print(len(F), 'findings;', Counter(f['prefix'] for f in F), Counter(f['tier'] for f in F), 'sprint0:', sum(bool(f.get('s0')) for f in F))
